-- In postgresql.conf or session:
SET random_page_cost = 1.1;
SET seq_page_cost = 1.0;

-- See how many distinct values a column really has
SELECT n_distinct
FROM pg_stats
WHERE schemaname = 'public'
  AND tablename  = 'orders'
  AND attname    = 'status';

-- Increase detail for a skewed column, then refresh statistics
ALTER TABLE orders ALTER COLUMN status SET STATISTICS 500;
ANALYZE orders (status);

EXPLAIN ANALYZE
SELECT count(*)
FROM orders
WHERE status = 'PENDING';
